// ─────────────────────────────────────────────────────────────────────────────
// Config & Safety Gate
// Reads every runtime setting from environment variables (urgency thresholds,
// enterprise rules, AI provider/model, routing, safety flags) and
// authenticates webhook deliveries with a shared secret (constant-time).
// SAFE-BY-DEFAULT: missing/unrecognised flags resolve to their safe value, so
// a fresh import makes zero CRM updates, zero Slack posts and zero AI calls.
// Secret VALUES are never copied into the item; webhook headers are dropped.
// ─────────────────────────────────────────────────────────────────────────────
let envAccessible = true;
try { void $env.SANDBOX_MODE; } catch (e) { envAccessible = false; }
const readEnv = (key) => {
  if (!envAccessible) return undefined;
  try { const v = $env[key]; return v === undefined || v === null ? undefined : String(v).trim(); } catch (e) { return undefined; }
};
const warnings = [];
if (!envAccessible) warnings.push('Environment access is blocked (N8N_BLOCK_ENV_ACCESS_IN_NODE=true). All safe defaults were applied.');

const flag = (key, safeDefault) => {
  const raw = readEnv(key);
  if (raw === undefined || raw === '') return safeDefault;
  const v = raw.toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  warnings.push(`${key} has an unrecognised value; using safe default (${safeDefault}).`);
  return safeDefault;
};
const num = (key, def, min, max) => {
  const raw = readEnv(key);
  if (raw === undefined || raw === '') return def;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < min || n > max) { warnings.push(`${key} must be a number between ${min} and ${max}; using default ${def}.`); return def; }
  return n;
};
const oneOf = (key, def, allowed) => {
  const raw = (readEnv(key) || '').toLowerCase();
  if (!raw) return def;
  if (allowed.includes(raw)) return raw;
  warnings.push(`${key} must be one of ${allowed.join(', ')}; using default ${def}.`);
  return def;
};

// ── Run clock
let runDate = new Date();
const tsOverride = readEnv('RUN_TIMESTAMP_OVERRIDE');
if (tsOverride) { const d = new Date(tsOverride); if (Number.isNaN(d.getTime())) warnings.push('RUN_TIMESTAMP_OVERRIDE is not a valid ISO date; using current time.'); else runDate = d; }

// ── Safety flags
const sandboxRequested = flag('SANDBOX_MODE', true);
const dryRun = flag('DRY_RUN', true);
const hubspotMutationsEnabled = flag('HUBSPOT_MUTATIONS_ENABLED', false);
const sendSlackAlerts = flag('SEND_SLACK_ALERTS', false);
const sendOpsAlerts = flag('SEND_OPS_ALERTS', false);
const aiAnalysisEnabled = flag('AI_ANALYSIS_ENABLED', false);
const redactPii = flag('REDACT_PII', true);
if (!redactPii) warnings.push('REDACT_PII=false: transcripts are sent to the AI provider and Slack without redaction.');

// ── Secret presence only
const present = (k) => Boolean(readEnv(k));
const hasHubspotToken = present('HUBSPOT_ACCESS_TOKEN');
const hasAiKey = present('AI_API_KEY');
const hasSlackWebhook = /^https:\/\//i.test(readEnv('SLACK_ALERT_WEBHOOK_URL') || '');
const hasLeadershipWebhook = /^https:\/\//i.test(readEnv('SLACK_LEADERSHIP_WEBHOOK_URL') || '');
const hasAlertWebhook = /^https:\/\//i.test(readEnv('ALERT_WEBHOOK_URL') || '');
const webhookSecret = readEnv('INBOUND_WEBHOOK_SECRET') || '';

// ── Trigger + inbound authentication (headers never leave this node)
const trig = $input.first() ? ($input.first().json || {}) : {};
const isWebhook = trig && typeof trig === 'object' && trig.headers && typeof trig.headers === 'object';
const secretHeader = (readEnv('INBOUND_WEBHOOK_SECRET_HEADER') || 'x-webhook-secret').toLowerCase();
const safeEqual = (a, b) => {
  const x = String(a); const y = String(b);
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) diff |= (x.charCodeAt(i % (x.length || 1)) || 0) ^ (y.charCodeAt(i % (y.length || 1)) || 0);
  return diff === 0 && x.length > 0;
};
let inboundAuth = 'not_applicable';
if (isWebhook) {
  if (!webhookSecret) inboundAuth = 'rejected_no_secret_configured';
  else {
    const given = Object.entries(trig.headers).find(([k]) => k.toLowerCase() === secretHeader);
    inboundAuth = given && safeEqual(given[1], webhookSecret) ? 'verified' : 'rejected_bad_secret';
  }
}
const inboundBody = isWebhook && inboundAuth === 'verified' ? (trig.body ?? null) : null;

// ── Live readiness
let sandboxMode = sandboxRequested;
if (!sandboxRequested && !hasHubspotToken) { sandboxMode = true; warnings.push('SANDBOX_MODE=false but HUBSPOT_ACCESS_TOKEN is missing. Forced back to sandbox fixtures.'); }
if (!sandboxRequested && !isWebhook) { sandboxMode = true; warnings.push('Live mode processes webhook deliveries only; a manual run uses sandbox fixtures.'); }
if (isWebhook && sandboxMode) warnings.push('Inbound webhook payload ignored because the workflow is in SANDBOX_MODE; synthetic fixtures were analysed instead.');

// ── AI provider
const aiProvider = oneOf('AI_PROVIDER', 'openai', ['openai', 'anthropic']);
const defaultModel = aiProvider === 'anthropic' ? 'claude-haiku-5-5' : 'gpt-4o-mini';
const aiModel = /^[A-Za-z0-9._:-]{1,80}$/.test(readEnv('AI_MODEL') || '') ? readEnv('AI_MODEL') : defaultModel;
const allowAiCall = aiAnalysisEnabled && hasAiKey;
if (aiAnalysisEnabled && !hasAiKey) warnings.push('AI_ANALYSIS_ENABLED=true but AI_API_KEY is missing; lexicon-only scoring used.');

// ── Thresholds (must be ascending)
let tMed = num('URGENCY_MEDIUM_THRESHOLD', 40, 1, 98);
let tHigh = num('URGENCY_HIGH_THRESHOLD', 65, 2, 99);
let tCrit = num('URGENCY_CRITICAL_THRESHOLD', 85, 3, 100);
if (!(tMed < tHigh && tHigh < tCrit)) { warnings.push('Urgency thresholds must be ascending (medium < high < critical); using defaults 40/65/85.'); tMed = 40; tHigh = 65; tCrit = 85; }

// ── Hard gates
const allowHubspotMutations = !sandboxMode && !dryRun && hubspotMutationsEnabled && hasHubspotToken;
const allowSlackSend = sendSlackAlerts && !dryRun && hasSlackWebhook;
const allowOpsAlert = sendOpsAlerts && !dryRun && hasAlertWebhook;
const mutationBlockedReason = allowHubspotMutations ? null : sandboxMode ? 'sandbox_mode' : dryRun ? 'dry_run' : !hubspotMutationsEnabled ? 'hubspot_mutations_disabled' : 'missing_hubspot_token';

const modeLabel = sandboxMode ? 'SANDBOX' : (dryRun ? 'LIVE-DRY-RUN' : 'LIVE');
const stamp = runDate.toISOString().replace(/[-:]/g, '').replace(/\..+$/, '').replace('T', '-');
const execId = (typeof $execution !== 'undefined' && $execution && $execution.id) ? String($execution.id) : 'manual';

return [{
  json: {
    runId: `cunr-${stamp}-${execId}`,
    runStartedAt: runDate.toISOString(),
    modeLabel,
    envAccessible,
    trigger: isWebhook ? 'webhook' : 'manual',
    inboundAuth,
    inboundBody,

    sandboxRequested, sandboxMode, dryRun, hubspotMutationsEnabled, sendSlackAlerts, sendOpsAlerts,
    aiAnalysisEnabled, redactPii,
    allowHubspotMutations, allowSlackSend, allowOpsAlert, allowAiCall, mutationBlockedReason,
    secretsPresent: { hasHubspotToken, hasAiKey, hasSlackWebhook, hasLeadershipWebhook, hasAlertWebhook, hasInboundWebhookSecret: Boolean(webhookSecret) },

    hubspotPortalId: /^\d{1,12}$/.test(readEnv('HUBSPOT_PORTAL_ID') || '') ? readEnv('HUBSPOT_PORTAL_ID') : '99000001',
    hubspotAppBaseUrl: /^https:\/\/app(-[a-z0-9]+)?\.hubspot\.com$/.test(readEnv('HUBSPOT_APP_BASE_URL') || '') ? readEnv('HUBSPOT_APP_BASE_URL') : 'https://app.hubspot.com',
    updateDeals: flag('UPDATE_DEAL_RECORDS', true),

    aiProvider, aiModel,
    aiTimeoutMs: Math.floor(num('AI_TIMEOUT_MS', 20000, 1000, 120000)),
    aiBlendWeight: num('AI_BLEND_WEIGHT', 0.6, 0, 1),
    aiDisagreementThreshold: num('AI_DISAGREEMENT_THRESHOLD', 35, 1, 100),
    maxTranscriptChars: Math.floor(num('MAX_TRANSCRIPT_CHARS', 20000, 500, 200000)),
    maxCallsPerDelivery: Math.floor(num('MAX_CALLS_PER_DELIVERY', 50, 1, 500)),

    thresholds: { medium: tMed, high: tHigh, critical: tCrit },
    sentimentNegativeThreshold: num('SENTIMENT_NEGATIVE_THRESHOLD', -0.25, -1, 0),
    sentimentPositiveThreshold: num('SENTIMENT_POSITIVE_THRESHOLD', 0.25, 0, 1),
    enterprise: {
      minEmployees: Math.floor(num('ENTERPRISE_MIN_EMPLOYEES', 1000, 1, 1e7)),
      minDealAmount: num('ENTERPRISE_MIN_DEAL_AMOUNT', 50000, 0, 1e12),
      minSeats: Math.floor(num('ENTERPRISE_MIN_SEATS', 250, 1, 1e7)),
    },
    escalationMinLevel: oneOf('ESCALATION_MIN_LEVEL', 'high', ['medium', 'high', 'critical']),
    escalateCriticalNonEnterprise: flag('ESCALATE_CRITICAL_NON_ENTERPRISE', true),
    escalationCooldownHours: num('ESCALATION_COOLDOWN_HOURS', 24, 0, 720),

    warnings,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Load Sandbox Fixture
// Emits one item per SYNTHETIC call (mirrors
// sample-payloads/call-transcript-fixture.json). The simulated CRM block is
// kept for the sandbox CRM lookup; "lastEscalatedHoursAgo" becomes a
// timestamp relative to this run. No network calls.
